head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//

/**
 * @method
 * @name CheckValues
 * @description desc
 * @param {string} fm desc
 * @param {string} mkt_rsn_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CheckValues = function(fm, mkt_rsn_cd) {
    var fm = document.SendForm;
    var _now_time = $("#areaNowTimer").val();
    var _isur_cd = fm.isur_cd.getValue();
    //신청버튼클릭시 시간체크
    if (!applTmCheck(mkt_rsn_cd, _now_time, _isur_cd)) {
        return false;
    }
    if (GetByte(fm.procs_req_dd.getValue()) == 0) {
        alert("적용희망일을 입력하십시오.");
        fm.procs_req_dd.focus();
        return;
    }

    //적용희망일 익일체크
    var procs_req_dd = Del_Hypen2(fm.procs_req_dd);
    var procsYear = parseInt(procs_req_dd.substr(0, 4), 10);
    var procsMonth = parseInt(procs_req_dd.substr(4, 2), 10);
    var procsDate = parseInt(procs_req_dd.substr(6, 2), 10);
    var today = new Date();
    var todayYear = today.getFullYear();
    var todayMonth = today.getMonth() + 1;
    var todayDate = today.getDate();
    if (procsYear < todayYear) {
        alert("적용희망일은 익일부터 신청가능합니다.");
        return;
    } else if ((procsYear == todayYear) && (procsMonth < todayMonth)) {
        alert("적용희망일은 익일부터 신청가능합니다.");
        return;
    } else if ((procsYear >= todayYear) && (procsMonth >= todayMonth)) {
        if ((procsMonth <= todayMonth) && (procsDate <= todayDate)) {
            alert("적용희망일은 익일부터 신청가능합니다.");
            return;
        }
    }
    if (mkt_rsn_cd == '205') {
        if (GetByte(fm.div_char_isu_nm.getValue()) == 0) {
            alert("분리 종목명을 입력하십시오.");
            fm.div_char_isu_nm.focus();
            return;
        } else {
            fm.ef_req_isu_nm.setValue(fm.div_std_isu_nm.getValue() + fm.div_char_isu_nm.getValue());
        }
        if (GetByte(fm.div_char_eng_isu_nm.getValue()) == 0) {
            alert("분리 영문 종목명을 입력하십시오.");
            fm.div_char_eng_isu_nm.focus();
            return;
        } else {
            fm.ef_req_eng_isu_nm.setValue(fm.div_std_eng_isu_nm.getValue() + fm.div_char_eng_isu_nm.getValue());
        }
        if (GetByte(fm.ef_exe_pr.getValue()) == 0) {
            alert("행사가격을 입력하십시오.");
            fm.ef_exe_pr.focus();
            return;
        }
        if (GetByte(fm.ef_exe_stk_cnt.getValue()) == 0) {
            alert("주식수를 입력하십시오.");
            fm.ef_exe_stk_cnt.focus();
            return;
        }
        if (GetByte(fm.ef_exe_amt.getValue()) == 0) {
            alert("행사금액을 입력하십시오.");
            fm.ef_exe_amt.focus();
            return;
        }
        if (GetByte(fm.ef_exe_dt.getValue()) == 0) {
            alert("행사일자를 입력하십시오.");
            fm.ef_exe_dt.focus();
            return;
        }
    } else if (mkt_rsn_cd == '301') {
        if (GetByte(fm.list_amt.getValue()) == 0) {
            alert("상장 금액을 입력하십시오.");
            fm.list_amt.focus();
            return;
        }
    } else if (mkt_rsn_cd == '302') {
        var isTrue = false;
        for (var cou = 0; cou < 10; cou++) {
            temp = new Array(4);
            temp[0] = fm["ef_exe_dt" + cou].getValue();
            temp[1] = fm["ef_exe_stk_cnt" + cou].getValue();
            temp[2] = fm["ef_exe_pr" + cou].getValue();
            temp[3] = fm["ef_exe_amt" + cou].getValue();

            //아무것도 입력하지 않았는지 Check
            for (var num = 0; num < 4; num++) {
                if (temp[num] != null && temp[num] != "") {
                    isTrue = true;
                }
            }

            //입력 항목 사이 누락여부 check
            for (var num = 0; num < 3; num++) {
                if ((GetByte(temp[num]) == 0) && (GetByte(temp[num + 1]) > 0)) {
                    switch (num) {
                        case 0:
                            alert("행사 일자를 입력하십시오.");
                            fm["ef_exe_dt" + cou].focus();
                            return;
                            break;
                        case 1:
                            alert("행사 주식수를 입력하십시오.");
                            fm["ef_exe_stk_cnt" + cou].focus();
                            return;
                            break;
                        case 2:
                            alert("행사 가격을 입력하십시오.");
                            fm["ef_exe_pr" + cou].focus();
                            return;
                            break;
                    }
                }
            }

            //입력 항목 누락 여부 check
            for (var num = 0; num < 3; num++) {
                if ((GetByte(temp[num]) > 0) && (GetByte(temp[num + 1]) == 0)) {
                    switch (num) {
                        case 0:
                            alert("행사 주식수를 입력하십시오.");
                            fm["ef_exe_stk_cnt" + cou].focus();
                            return;
                            break;
                        case 1:
                            alert("행사 가격을 입력하십시오.");
                            fm["ef_exe_pr" + cou].focus();
                            return;
                            break;
                        case 2:
                            alert("행사 금액을 입력하십시오.");
                            fm["ef_exe_amt" + cou].focus();
                            return;
                            break;
                    }
                }
            }
        }
        if (isTrue == false) {
            fm.ef_exe_dt0.focus();
            alert("행사 일자를 입력하십시오.");
            return;
        }
    } else if (mkt_rsn_cd == '303') {
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("등록 말소일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
        if (GetByte(fm.ef_rdmp_amt.getValue()) == 0) {
            alert("일부 중도 상환 금액을 입력하십시오.");
            fm.ef_rdmp_amt.focus();
            return;
        }
    } else if (mkt_rsn_cd == '304') {
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("등록 말소일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
    } else if (mkt_rsn_cd == '305') {
        if (GetByte(fm.ef_add_iss_amt.getValue()) == 0) {
            alert("추가 발행 금액을 입력하십시오.");
            fm.ef_add_iss_amt.focus();
            return;
        }
        if (GetByte(fm.coupn_rt.getValue()) == 0) {
            alert("표면 이자율(낙찰 금리)을 입력하십시오.");
            fm.coupn_rt.focus();
            return;
        }
        if (GetByte(fm.ef_add_iss_dt.getValue()) == 0) {
            alert("추가 발행일을 입력하십시오.");
            fm.ef_add_iss_dt.focus();
            return;
        }
    } else if (mkt_rsn_cd == '306') {
        if (GetByte(fm.stk_rel_corpbnd_exer_prc.getValue()) == 0) {
            alert("변경후 권리행사가액을 입력하십시오.");
            fm.stk_rel_corpbnd_exer_prc.focus();
            return;
        }
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("사유발생일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
        if (fm.chg_rsn_contn1.options[0].selected) {
            alert("변경사유_1을 선택해 주십시오.");
            fm.chg_rsn_contn1.focus();
            return;
        }
        //기타선택시 사유입력        
        if (fm.chg_rsn_contn1.options[9].selected) {
            if (GetByte(fm.chg_rsn_contn2.getValue()) == 0) {
                alert("기타 변경사유를 입력해 주십시오.");
                fm.chg_rsn_contn2.focus();
                return;
            }
        }
    } else if (mkt_rsn_cd == '307') {
        if (GetByte(fm.bnd_isu_prc.getValue()) == 0) {
            alert("변경후 발행가액을 입력하십시오.");
            fm.bnd_isu_prc.focus();
            return;
        }
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("사유발생일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
    } else if (mkt_rsn_cd == '308') {
        if (GetByte(fm.coupn_rt.getValue()) == 0) {
            alert("변경후 이자율을 입력하십시오.");
            fm.coupn_rt.focus();
            return;
        }
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("사유발생일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
        if (GetByte(fm.chg_rsn.getValue()) == 0) {
            alert("변경사유를 입력하십시오.");
            fm.chg_rsn.focus();
            return;
        }

        //마이너스입력체크
        if (fn_minusCheck(fm.coupn_rt, "표면이자율") == "N") {
            return false;
        }

    } else if (mkt_rsn_cd == '309') {
        //금리결정기준일
        if (GetByte(fm.int_rt_decsn_bas_dd.getValue()) == 0) {
            alert('금리결정기준일을 입력하십시오.');
            fm.int_rt_decsn_bas_dd.focus();
            return;
        }
        //이자지급일 필수아님.. 2월반영 예정
        //if (GetByte(fm.int_pay_dd.value) == 0) {
        //alert('이자지급일을 입력하십시오.');
        //fm.int_pay_dd.focus();
        //return;
        //}

        //기준금리구분코드 항상 선택되므로 체크제외
        //기준금리
        if (GetByte(fm.nxtpd_bas_int.getValue()) == 0) {
            alert("기준금리를 입력하십시오.");
            fm.nxtpd_bas_int.focus();
            return;
        }
        //가산금리부호
        if (GetByte(fm.spd_sgn.getValue()) == 0) {
            alert('가산금리의 부호를 선택하십시오.');
            fm.spd_sgn.focus();
            return;
        }
        //가산금리
        if (GetByte(fm.spd.getValue()) == 0) {
            alert('가산금리를 입력하십시오.');
            fm.spd.focus();
            return;
        }
        //기타기준금리
        //if (GetByte(fm.int_rt_decsn_misc_bas_int_nm.value) == 0) {
        //    alert('기타기준금리를 입력하십시오.');
        //    fm.int_rt_decsn_misc_bas_int_nm.focus();
        //    return;
        //}
        //if (GetByte(fm.int_rt_decsn_misc_bas_int_nm.value) > 20) {
        //    alert("기타기준금리를 한글10자, 영문20자 이내로 입력해 주십시오.");
        //    fm.int_rt_decsn_misc_bas_int_nm.focus();
        //    return;
        //}

        //마이너스입력체크
        if (fn_minusCheck(fm.nxtpd_bas_int, "기준금리") == "N") {
            return false;
        }

    } else if (mkt_rsn_cd == '311') {
        if (GetByte(fm.redmpt_dd.getValue()) == 0) {
            alert("변경후 상환일을 입력하십시오.");
            fm.redmpt_dd.focus();
            return;
        }
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("사유발생일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
        if (GetByte(fm.chg_rsn.getValue()) == 0) {
            alert("사유를 입력하십시오.");
            fm.chg_rsn.focus();
            return;
        }

        //변경후 상환일과 최초이자지급일을 비교
        var v_bf_fst_int_pay_dd = $c.ut.replaceAll(fm.bf_fst_int_pay_dd.getValue(), "-", ""); //변경전 최초이자지급일
        var v_redmpt_dd = $c.ut.replaceAll(fm.redmpt_dd.getValue(), "-", ""); //변경후 상환일

        //비교 
        if (v_bf_fst_int_pay_dd > v_redmpt_dd) {
            //최초이자지급일 div표시여부
            if (fm.fst_int_pay_dd_view_yn.getValue() == "N") {
                if (!confirm("변경후 상환일이 최초이자지급일(" + v_bf_fst_int_pay_dd + ") 이전입니다.\n\n최초이자지급일을 변경하시겠습니까?")) {
                    fm.fst_int_pay_dd_view_yn.setValue("N");
                    $("#tr_fst_int_pay_dd").hide();
                    return false;
                } else {
                    fm.fst_int_pay_dd.setValue("");
                    fm.fst_int_pay_dd_view_yn.setValue("Y");
                    $("#tr_fst_int_pay_dd").show();
                }
            }
        } else {
            fm.fst_int_pay_dd_view_yn.setValue("N");
            $("#tr_fst_int_pay_dd").hide();
        }
        if (fm.fst_int_pay_dd_view_yn.getValue() == "Y") {
            if (GetByte(fm.fst_int_pay_dd.getValue()) == 0) {
                alert("변경후 최초이자지급일을 입력하십시오.");
                fm.fst_int_pay_dd.focus();
                return;
            }
        } else {
            fm.fst_int_pay_dd.setValue(fm.bf_fst_int_pay_dd.getValue());
        }
        //alert("변경후 상환일이 최초이자지급일(20170101) 이전입니다.");

    } else if (mkt_rsn_cd == '312') {
        if (fm.cb_grt_req_cd.options[2].selected) {
            if (GetByte(fm.grt_inst_nm.getValue()) == 0) {
                alert("변경 후 보증 기관을 입력하십시오.");
                fm.grt_inst_nm.focus();
                return;
            }
        }
        if (fm.cb_grt_req_cd.options[0].selected) {
            alert("변경 종류를 선택하십시오.");
            fm.cb_grt_req_cd.focus();
            return;
        }
        if (GetByte(fm.ef_chg_rsn.getValue()) == 0) {
            alert("사유를 입력하십시오.");
            fm.ef_chg_rsn.focus();
            return;
        }
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("사유발생일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
        if (fm.cb_grt_req_cd.options[1].selected) {
            fm.mkt_rsn_cd.setValue('312');
        } else if (fm.cb_grt_req_cd.options[2].selected) {
            fm.mkt_rsn_cd.setValue('318');
        } else if (fm.cb_grt_req_cd.options[3].selected) {
            fm.mkt_rsn_cd.setValue('319');
        } else {
            alert("변경 종류를 선택하십시오.");
        }
    } else if (mkt_rsn_cd == '315') {
        if (GetByte(fm.ef_exe_amt.getValue()) == 0) {
            alert("행사금액을 입력하십시오.");
            fm.ef_exe_amt.focus();
            return;
        }
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("사유발생일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
    } else if (mkt_rsn_cd == '316') {
        if (GetByte(fm.chg_dtl_contn.getValue()) == 0) {
            alert("변경내역을 입력하십시오.");
            fm.chg_dtl_contn.focus();
            return;
        }
        if (GetByte(fm.rsn_occr_dd.getValue()) == 0) {
            alert("사유발생일을 입력하십시오.");
            fm.rsn_occr_dd.focus();
            return;
        }
    } else if (mkt_rsn_cd == '320') {
        fm.fst_sale_dd_yn.setValue('N');
        if (fm.ck_fst_sale_dd_yn.checked) {
            fm.fst_sale_dd_yn.setValue('Y');
        }
        if (GetByte(fm.sale_dd.getValue()) == 0) {
            alert("매출일을 입력하십시오.");
            fm.sale_dd.focus();
            return;
        }
        if (GetByte(fm.bnd_tot_sales.getValue()) == 0) {
            alert("일중 매출총액을 입력하십시오.");
            fm.bnd_tot_sales.focus();
            return;
        }
        if (GetByte(fm.redmpt_amt.getValue()) == 0) {
            alert("일중 중도상환액을 입력하십시오.");
            fm.redmpt_amt.focus();
            return;
        }
    } else if (mkt_rsn_cd == '330') {
        //WIT종목정보확정

        //상장희망일 - 매매일체크
        Chk_Mkt_Holdy(fm.procs_req_dd);
        if (fm.procs_req_dd_check.getValue() == 'Y') {
            alert("상장희망일은  매매일만 입력가능합니다.");
            fm.procs_req_dd.focus();
            return;
        }
        if (GetByte(fm.unq_isu_nm.getValue()) == 0) {
            alert("변경후 한글고유명을 입력하십시오.");
            fm.unq_isu_nm.focus();
            return;
        }
        if (GetByte(fm.unq_isu_eng_nm.getValue()) == 0) {
            alert("변경후 영문고유명을 입력하십시오.");
            fm.unq_isu_nm.focus();
            return;
        }
        if (GetByte(fm.coupn_rt.getValue()) == 0) {
            alert("변경후 표면이자율을 입력하십시오.");
            fm.coupn_rt.focus();
            return;
        }
        if (GetByte(fm.isu_amt.getValue()) == 0) {
            alert("변경후 발행금액을 입력하십시오.");
            fm.isu_amt.focus();
            return;
        }
        if (GetByte(fm.list_amt.getValue()) == 0) {
            alert("변경후 상장금액을 입력하십시오.");
            fm.list_amt.focus();
            return;
        }
        if (GetByte(fm.scbd_int.getValue()) == 0) {
            alert("낙찰금리를 입력하십시오.");
            fm.scbd_int.focus();
            return;
        }

        //마이너스입력체크
        if (fn_minusCheck(fm.coupn_rt, "표면이자율") == "N") {
            return false;
        }
        if (fn_minusCheck(fm.scbd_int, "낙찰금리") == "N") {
            return false;
        }

    }

    //파일체크
    if (!scwin.CheckFileList(fm)) {
        return;
    }

    // 첨부파일 크기 체크(전체 파일사이즈 <= 100)  2024.05.14 by 김효준
    var totFileSize = sumAttachedFilesSize(); // MB
    if (totFileSize > 100) {
        alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }

    // FRN변동금리, 표면이자율변경,
    if (mkt_rsn_cd != '309' && mkt_rsn_cd != '308' && mkt_rsn_cd != '307' && mkt_rsn_cd != '306' && mkt_rsn_cd != '311' && mkt_rsn_cd != '316') {
        //신청인사항
        if (!CheckReqInfo(fm)) {
            return;
        }
    }

    //권리행사가액(306), FRN변동금리(309) 휴대전화번호체크 + 표면이자율, 발행가액, 상환일, 기타변경, WIT종목정보확정
    if (mkt_rsn_cd == '306' || mkt_rsn_cd == '309' || mkt_rsn_cd == '308' || mkt_rsn_cd == '307' || mkt_rsn_cd == '311' || mkt_rsn_cd == '316' || mkt_rsn_cd == '330' || mkt_rsn_cd == '301' || mkt_rsn_cd == '320') {
        if (!CheckReqInfo_Cellphone(fm)) {
            return;
        }
    }
    if (!confirm("신청하시겠습니까?")) {
        return false;
    }
    if (mkt_rsn_cd == '320') {
        //저장버튼 숨김
        $("#reg_button").hide();
    }
    fm.method.setValue("saveIsuInfoChg");
    fm.action = "/event/event.do";
    fm.target = "_self";
    fm.submit();
};
