// 권리행사(일반사채)
/**
 * @method
 * @name add_exe_amt
 * @description desc
 * @param {string} ef_exe_amt desc
 * @param {string} bf_lst_amt desc
 * @param {string} bf_iss_amt desc
 * @param {string} af_lst_amt desc
 * @param {string} af_iss_amt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.add_exe_amt = function(ef_exe_amt, bf_lst_amt, bf_iss_amt, af_lst_amt, af_iss_amt) {
    if (GetByte(ef_exe_amt.getValue()) == 0) {
        af_lst_amt.setValue('');
        af_iss_amt.setValue('');
        return;
    }
    var V_exe_amt = Del_MoneyComma_Value(ef_exe_amt.getValue());
    if (!Chk_Digit(V_exe_amt)) {
        af_lst_amt.setValue('');
        af_iss_amt.setValue('');
        return;
    }
    var V_bf_lst_amt = Del_MoneyComma_Value(bf_lst_amt.getValue());
    var V_bf_iss_amt = Del_MoneyComma_Value(bf_iss_amt.getValue());
    var V_af_lst_amt = parseInt(V_bf_lst_amt) + parseInt(V_exe_amt);
    var V_af_iss_amt = parseInt(V_bf_iss_amt) + parseInt(V_exe_amt);
    if (V_af_lst_amt.length > 12) {
        alert("변경후 상장금액이 12자리를 초과하였습니다. 다시 입력하십시오.");
        af_lst_amt.setValue(0);
        ef_exe_amt.focus();
        return;
    } else if (V_af_iss_amt.length > 12) {
        alert("변경후 발행금액이 12자리를 초과하였습니다. 다시 입력하십시오.");
        af_iss_amt.setValue(0);
        ef_exe_amt.focus();
        return;
    } else {
        af_lst_amt.setValue(V_af_lst_amt);
        af_iss_amt.setValue(V_af_iss_amt);
        Add_MoneyComma(af_lst_amt);
        Add_MoneyComma(af_iss_amt);
        return;
    }
};
/**
 * @method
 * @name Cal_af_iss_amt
 * @description desc
 * @param {string} ef_add_iss_amt desc
 * @param {string} bf_iss_amt desc
 * @param {string} af_iss_amt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Cal_af_iss_amt = function(ef_add_iss_amt, bf_iss_amt, af_iss_amt) {
    if (GetByte(ef_add_iss_amt.getValue()) == 0) {
        return;
    }
    var ef_add_iss_amt = Del_MoneyComma_Value(ef_add_iss_amt.getValue());
    var bf_iss_amt = Del_MoneyComma_Value(bf_iss_amt.getValue());
    if (!Chk_Digit(ef_add_iss_amt)) {
        return false;
    }

    // 변경전 발행금액 + 추가 발행금액
    var cal = parseInt(bf_iss_amt) + parseInt(ef_add_iss_amt);
    af_iss_amt.setValue(cal);
    Add_MoneyComma(af_iss_amt);
    return true;
};
/**
 * @method
 * @name Cal_af_lst_amt
 * @description desc
 * @param {string} ef_rdmp_amt desc
 * @param {string} bf_lst_amt desc
 * @param {string} af_lst_amt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Cal_af_lst_amt = function(ef_rdmp_amt, bf_lst_amt, af_lst_amt) {
    var cal;
    var mid;
    var lst;
    mid = Del_MoneyComma_Value(ef_rdmp_amt.getValue());
    lst = Del_MoneyComma_Value(bf_lst_amt.getValue());
    if (!Chk_Digit(mid)) {
        return false;
    }

    // 변경전 상장 잔액 - 일부 중도 상환금액
    cal = lst - mid;
    if (cal < 0) {
        alert("상장 잔액금액을 초과하였습니다. 다시 입력하십시오.");
        af_lst_amt.setValue(0);
        ef_rdmp_amt.focus();
        return false;
    } else {
        af_lst_amt.setValue(cal);
        Add_MoneyComma(af_lst_amt);
        return true;
    }
};



// 컴마(",") 자동 삭제
/**
 * @method
 * @name Del_Comma
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Del_Comma = function(Name) {
    var x, ch;
    var i = 0;
    var newVal = "";
    for (x = 0; x < Name.length; x++) {
        ch = Name.substring(x, x + 1);
        if (ch != ",") newVal += ch;
    }
    return newVal;
};


// 금액 입력시 "," 자동 입력 & 우측 정렬
/**
 * @method
 * @name Add_Money
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Add_Money = function(Name) {
    var src;
    var i;
    var factor;
    var su;
    var SpaceSize = 0;
    if (!Chk_Digit(Name.getValue())) {
        alert(" 숫자만 입력 가능합니다.");
        Name.focus();
        return false;
    }
    scwin.Add_Total();
    factor = Name.getValue().length % 3;
    su = (Name.getValue().length - factor) / 3;
    src = Name.getValue().substring(0, factor);
    for (i = 0; i < su; i++) {
        if ((factor == 0) && (i == 0)) {
            // "XXX" 인경우
            src += Name.getValue().substring(factor + (3 * i), factor + 3 + (3 * i));
        } else {
            src += ",";
            src += Name.getValue().substring(factor + (3 * i), factor + 3 + (3 * i));
        }
    }
    Name.setValue(src);
    return true;
};


// 행사주식수, 행사가격, 행사금액 합계 "," 자동 입력 & 우측 정렬
/**
 * @method
 * @name Add_Comma
 * @description desc
 * @param {string} Name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Add_Comma = function(Name) {
    var src;
    var i;
    var factor;
    var su;
    var SpaceSize = 0;
    factor = Name.length % 3;
    su = (Name.length - factor) / 3;
    src = Name.substring(0, factor);
    for (i = 0; i < su; i++) {
        if ((factor == 0) && (i == 0)) {
            // "XXX" 인경우
            src += Name.substring(factor + (3 * i), factor + 3 + (3 * i));
        } else {
            src += ",";
            src += Name.substring(factor + (3 * i), factor + 3 + (3 * i));
        }
    }
    Name = src;
    return Name;
};



//행사주식수, 행사가격, 행사금액 합계 보여주기
/**
 * @method
 * @name Add_Total
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Add_Total = function() {
    fm = document.SendForm;
    var tot_stk_cnt = 0;
    var conv_pr = 0;
    var tot_conv_amt = 0;
    var exe_last_dt = '';
    var af_last_amt;
    for (var i = 0; i < 10; i++) {
        if (fm["ef_exe_stk_cnt" + i].getValue() != null && fm["ef_exe_stk_cnt" + i].getValue() != '') {
            tot_stk_cnt += parseInt(scwin.Del_Comma(fm["ef_exe_stk_cnt" + i].getValue()));
        }
        if (fm["ef_exe_pr" + i].getValue() != null && fm["ef_exe_pr" + i].getValue() != '') {
            conv_pr += parseInt(scwin.Del_Comma(fm["ef_exe_pr" + i].getValue()));
        }
        if (fm["ef_exe_amt" + i].getValue() != null && fm["ef_exe_amt" + i].getValue() != '') {
            if (parseInt(scwin.Del_Comma(fm["ef_exe_amt" + i].getValue())) > parseInt(scwin.Del_Comma(fm.lst_amt.getValue()))) {
                alert("전환(행사)금액이 변경 전 상장 금액을 초과 하였습니다.");
                fm["ef_exe_amt" + i].focus();
                return false;
            }
            tot_conv_amt += parseInt(scwin.Del_Comma(fm["ef_exe_amt" + i].getValue()));
        }
        if (fm["ef_exe_dt" + i].getValue() != null && fm["ef_exe_dt" + i].getValue() != '') {
            exe_last_dt = fm["ef_exe_dt" + i].getValue();
        }
    }
    fm.ef_tot_stk_cnt.setValue(scwin.Add_Comma(tot_stk_cnt + ''));
    fm.ef_conv_pr.setValue(scwin.Add_Comma(conv_pr + ''));
    af_last_amt = parseInt(scwin.Del_Comma(fm.lst_amt.getValue())) - tot_conv_amt;
    if (af_last_amt < 0) {
        alert("총 전환(행사)금액이 변경 전 상장 금액을 초과 하였습니다.");
        fm.ef_exe_amt0.focus();
        return false;
    }
    fm.ef_tot_conv_amt.setValue(scwin.Add_Comma(tot_conv_amt + ''));
    fm.ef_exe_last_dt.setValue(exe_last_dt);
    fm.af_last_amt.setValue(scwin.Add_Comma(af_last_amt + '')); // 변경 후 상장 잔액

};





// 입력날짜를 Check
/**
 * @method
 * @name Select_Date
 * @description desc
 * @param {string} Name desc
 * @param {string} Date_Str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Select_Date = function(Name, Date_Str) {
    var sdate = Name.getValue();
    var src;
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(4, 2);
    pday = sdate.substr(6, 2);
    src = pyear + '.' + pmonth + '.' + pday;
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate != "" && (syear != soyear || smonth != somonth || sday != soday)) {
        alert("입력한 " + Date_Str + "이 올바르지 않습니다 \n\r");
        Name.focus();
        return false;
    }
    if (sdate == "") Name.setValue('');

    else Name.setValue(src);
    scwin.Select_Last();
    return true;
};
