/**
 * @method
 * @name Cal_af_div_lst_amt
 * @description desc
 * @param {string} ef_exe_amt desc
 * @param {string} lst_amt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Cal_af_div_lst_amt = function(ef_exe_amt, lst_amt) {
    var cal;
    var mid;
    var lst;
    mid = Del_MoneyComma_Value(ef_exe_amt.getValue());
    lst = Del_MoneyComma_Value(lst_amt.getValue());
    if (!Chk_Digit(mid)) {
        return false;
    }

    // 변경전 상장 잔액 - 일부 중도 상환금액
    cal = lst - mid;
    if (cal < 0) {
        alert("행사 금액 " + ef_exe_amt.getValue() + "천원이 상장 잔액 " + lst_amt.getValue() + "천원보다 많습니다. 다시 입력하십시오.");
        ef_exe_amt.focus();
        return false;
    } else {
        return true;
    }
};
